CREATE TABLE IF NOT EXISTS `smsCodes` (
	`id` int AUTO_INCREMENT NOT NULL PRIMARY KEY,
	`phone` varchar(20) NOT NULL,
	`code` varchar(6) NOT NULL,
	`type` enum('login','register','bind') NOT NULL DEFAULT 'login',
	`used` int NOT NULL DEFAULT 0,
	`expiresAt` timestamp NOT NULL,
	`createdAt` timestamp NOT NULL DEFAULT (now())
);

ALTER TABLE `users` ADD COLUMN IF NOT EXISTS `phone` varchar(20);

CREATE INDEX IF NOT EXISTS `smsCodes_phone_idx` ON `smsCodes` (`phone`);

CREATE INDEX IF NOT EXISTS `users_phone_unique` ON `users` (`phone`);

